#include <bits/stdc++.h>
using namespace std;

const int N = 1000000007, P = 140, Q = 2000010;
long long soorat[P], choose[P][P], dp[P][P], ans[Q], choose2[2][P];
int n, p, q;
long long finalans;

void fillchoose(int ii, int j) {
	int nn = n - ii, jc = j, ss = nn - jc + 1;

	if (j == 0 || nn < 0 || ss < 0)
		return;

	for (int i = ss; i <= nn; i++)
		soorat[i - ss] = static_cast<unsigned>(i);

	for (; j > 0; j--) {
		long long x = j, gcdtmp;
		for (int i = ss; i <= nn && x > 1; i++) {
			gcdtmp = __gcd(soorat[i - ss], x);
			soorat[i - ss] /= gcdtmp;
			x /= gcdtmp;
		}
	}

	choose[ii][jc] = 1;
	for (int i = ss; i <= nn; i++)
		choose[ii][jc] *= static_cast<unsigned>(soorat[i - ss]);
}

void filldp(int i, int j) {
	for (int k = 1; k <= min(i, n - p + i - 1); k++)
		dp[i][j] += choose[p - i][k] * dp[i - k][j - 1];
}

void fillans(int t) {
	choose2[t % 2][0] = 1;
	for (int i = 1; i <= p; i++)
		choose2[t % 2][i] =
			choose2[1 - (t % 2)][i] + choose2[1 - (t % 2)][i - 1];

	for (int i = 0; i <= p; i++)
		ans[t] += choose2[t % 2][i] * dp[p][i];

	ans[t] = static_cast<unsigned>(ans[t] * t);
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> n >> p >> q;

	for (int i = 0; i <= p; i++)
		for (int j = 0; j <= p; j++)
			fillchoose(i, j);

	for (int i = 0; i <= p; i++)
		dp[i][0] = 1;

	for (int j = 1; j <= p; j++)
		for (int i = 0; i <= p; i++)
			filldp(i, j);

	choose2[0][0] = 1;

	for (int t = 1; t <= q; t++)
		fillans(t);

	for (int i = 1; i <= q; i++)
		finalans ^= ans[i];

	cout << finalans << '\n';

	return 0;
}

